/** Independent local TEMP-only driver challenge. No hosted URL or persistent-table writes. */
import {writeFile} from 'node:fs/promises'
import {createPostgresConnection} from '../../packages/neuvetra-database/src/hosted'
const db=createPostgresConnection('postgres://supabase_admin@127.0.0.1:55472/m78_ops_continuation_20260922',{tls:false,maxConnections:1});const check=(v:unknown)=>{if(!v)throw Error('Local timestamp challenge failed')};
try{const result=await db.transaction(async tx=>{await tx.exec('create temp table m78_independent_timestamp (id integer primary key,subject integer,created_at timestamptz,updated_at timestamptz) on commit drop');const times=['2026-09-22 18:49:13.40455+00','2026-09-22 18:49:13.67552+00','2026-09-22 18:49:13.854837+00','2026-09-22 18:49:14.000115+00'];for(let i=0;i<times.length;i++)await tx.query('insert into m78_independent_timestamp values($1,42,$2::text::timestamptz,$2::text::timestamptz)',[i,times[i]]);await tx.query('insert into m78_independent_timestamp values(99,43,$1::text::timestamptz,$1::text::timestamptz)',[times[0]]);const before=(await tx.query('select id,subject,created_at::text,updated_at::text from m78_independent_timestamp order by id')).rows;
await tx.exec('savepoint before_deletes');let oldDeleted=0,fixedDeleted=0;for(let i=0;i<4;i++){oldDeleted+=(await tx.query('delete from m78_independent_timestamp where id=$1 and subject=42 and created_at=$2::timestamptz and updated_at=$3::timestamptz returning id',[i,times[i],times[i]])).rows.length;check((await tx.query('delete from m78_independent_timestamp where id=$1 and subject=999 and created_at=$2::text::timestamptz and updated_at=$3::text::timestamptz returning id',[i,times[i],times[i]])).rows.length===0);fixedDeleted+=(await tx.query('delete from m78_independent_timestamp where id=$1 and subject=42 and created_at=$2::text::timestamptz and updated_at=$3::text::timestamptz returning id',[i,times[i],times[i]])).rows.length}check(oldDeleted===0&&fixedDeleted===4);check(JSON.stringify((await tx.query('select id,subject,created_at::text,updated_at::text from m78_independent_timestamp order by id')).rows)===JSON.stringify(before.filter((r:any)=>r.id===99)));await tx.exec('rollback to savepoint before_deletes');check(JSON.stringify((await tx.query('select id,subject,created_at::text,updated_at::text from m78_independent_timestamp order by id')).rows)===JSON.stringify(before));return{status:'m78_independent_v3_driver_regression_passed',oldDeleted,fixedDeleted,wrongSubjectDeleted:0,nonselectedPreserved:true,savepointRollbackRestoredAll:true,fixtures:4,temporaryOnly:true,hostedCalls:0,authenticationWrites:0}});await writeFile('evaluations/research-qa/m78-interrupted-session-cleanup-v3-native-result.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(result))}finally{await db.close()}

import {readFile,writeFile} from 'node:fs/promises';
import {connectOperator} from '../tools/staging/m77-common';
import {hostedDumpEnvironment} from '../tools/staging/m78-hosted-database';
import {inventory} from '../tools/staging/m78-inventory';
const sha=(v:string)=>new Bun.CryptoHasher('sha256').update(v).digest('hex');
const hash=(v:unknown)=>sha(JSON.stringify(v));
function check(v:unknown):asserts v{if(!v)throw Error('Exact interrupted-session cleanup refused');}
const path='.superpowers/m78-interrupted-sessions-observed.json';
const text=await readFile(path,'utf8');
check(sha(text)==='4570ae628e05c71d8feab14acc6e5c04fe985f842ab2cdf8d111b19031d1f273');
for(const [path,expected] of [
 ['.superpowers/m78-interrupted-session-cleanup-intent.json','30aa7e0076dd3e37fce77c74df632e81fed41624b2e000278bc37a68e0d24f28'],
 ['.superpowers/m78-interrupted-sessions-after-cleanup-attempt.json','bab3732a77b1457b9e8a480e255abcd13519e4fc49fd2e9606c8ea3ee94c5a3b'],
 ['.superpowers/m78-session-cleanup-diagnostic-result.json','d983093e047c46b19f820486d60210d7337df1385d46bd06cb3eabd5552a0f46']
 ] as const){check(sha(await readFile(path,'utf8'))===expected);}
const observed=JSON.parse(text);
check(observed.observations.length===4&&observed.observations.every((o:any)=>o.sessions.length===1&&o.refreshCounts.length===1&&o.refreshCounts[0].count==='1'));
const selected=observed.observations.map((o:any)=>({...o.sessions[0],role:o.role}));
check(new Set(selected.map((s:any)=>s.id)).size===4&&new Set(selected.map((s:any)=>s.user_id)).size===4);
const ids=selected.map((s:any)=>s.id);
const input=JSON.parse(await Bun.stdin.text());
check(input.operatorId==='/root'&&Object.keys(input).sort().join(',')==='operatorDatabaseUrl,operatorId');
hostedDumpEnvironment(input.operatorDatabaseUrl);
const intentPath='.superpowers/m78-interrupted-session-cleanup-v3-intent.json';
await writeFile(intentPath,JSON.stringify({status:'cleanup_intent_only',createdAt:new Date().toISOString(),observationSha256:sha(text),selected,tokenUsability:'not_verified',expiryVerified:false},null,2)+'\n',{flag:'wx'});
let stage='connect',commitReturned=false;
const db=await connectOperator(input.operatorDatabaseUrl);
try{
 const result=await db.transaction(async tx=>{
  await tx.exec('set transaction isolation level serializable');
  const identity=(await tx.query<any>("select current_database() database,current_user actor,current_setting('transaction_isolation') isolation")).rows[0];
  check(identity.database==='postgres'&&identity.actor==='postgres'&&identity.isolation==='serializable');
  stage='foreign_keys';const fks=(await tx.query<any>("select conname,conrelid::regclass::text as child_table,confrelid::regclass::text as parent_table,pg_get_constraintdef(oid) as definition from pg_constraint where contype='f' and confrelid='auth.sessions'::regclass order by conname")).rows;
  check(fks.length===2&&fks.every((f:any)=>['auth.refresh_tokens','auth.mfa_amr_claims'].includes(f.child_table)&&f.parent_table==='auth.sessions'&&f.definition==='FOREIGN KEY (session_id) REFERENCES auth.sessions(id) ON DELETE CASCADE'));
  stage='triggers';const triggers=(await tx.query<any>("select tgname from pg_trigger where not tgisinternal and tgrelid in ('auth.sessions'::regclass,'auth.refresh_tokens'::regclass,'auth.mfa_amr_claims'::regclass)")).rows;
  check(triggers.length===0);
  const sessionRows=async()=> (await tx.query<any>('select id,user_id,created_at,updated_at,created_at::text as created_at_exact,updated_at::text as updated_at_exact from auth.sessions order by id limit 10001')).rows;
  const linkedCounts=async(table:'refresh_tokens'|'mfa_amr_claims')=>(await tx.query<any>(`select session_id,count(*)::text as count from auth.${table} group by session_id order by session_id nulls first limit 10001`)).rows;
  stage='metadata_before';const before=await sessionRows(),refreshBefore=await linkedCounts('refresh_tokens'),mfaBefore=await linkedCounts('mfa_amr_claims');
  check(before.length<=10000&&refreshBefore.length<=10000&&mfaBefore.length<=10000);
  const iso=(v:any)=>new Date(v).toISOString();
  for(const s of selected){
   const matches=before.filter((r:any)=>r.id===s.id);
   check(matches.length===1&&matches[0].user_id===s.user_id&&iso(matches[0].created_at)===s.created_at&&iso(matches[0].updated_at)===s.updated_at);
   check(refreshBefore.filter((r:any)=>r.session_id===s.id&&r.count==='1').length===1);
  }
  stage='application_before';const appBefore=await inventory(tx);
  const deleted=[];
  for(const s of selected){
   const exact=before.find((r:any)=>r.id===s.id);check(exact&&typeof exact.created_at_exact==='string'&&typeof exact.updated_at_exact==='string');
   stage='delete_'+s.role;const rows=(await tx.query<any>('delete from auth.sessions where id=$1 and user_id=$2 and created_at=$3::text::timestamptz and updated_at=$4::text::timestamptz returning id',[s.id,s.user_id,exact.created_at_exact,exact.updated_at_exact])).rows;
   check(rows.length===1&&rows[0].id===s.id);deleted.push(s.id);
  }
  stage='metadata_after';const after=await sessionRows(),refreshAfter=await linkedCounts('refresh_tokens'),mfaAfter=await linkedCounts('mfa_amr_claims'),appAfter=await inventory(tx);
  check(!after.some((r:any)=>ids.includes(r.id))&&!refreshAfter.some((r:any)=>ids.includes(r.session_id))&&!mfaAfter.some((r:any)=>ids.includes(r.session_id)));
  stage='preservation';check(hash(before.filter((r:any)=>!ids.includes(r.id)))===hash(after));
  check(hash(refreshBefore.filter((r:any)=>!ids.includes(r.session_id)))===hash(refreshAfter));
  check(hash(mfaBefore.filter((r:any)=>!ids.includes(r.session_id)))===hash(mfaAfter));
  check(hash(appBefore)===hash(appAfter));
  return {status:'m78_exact_interrupted_sessions_removed',observedAt:new Date().toISOString(),identity,observationSha256:sha(text),selected,deletedIds:deleted,sessionRowsRemoved:4,linkedRowsAbsent:true,nonselectedSessionsPreserved:true,nonselectedLinkedCountsPreserved:true,applicationInventorySha256:hash(appAfter),applicationWrites:0,applicationInventoryPreserved:true,tokenUsability:'not_verified',expiryVerified:false};
 });
 commitReturned=true;stage='receipt';
 await writeFile('.superpowers/m78-interrupted-session-cleanup-v3-result.json',JSON.stringify({...result,commitReturned:true},null,2)+'\n',{flag:'wx'});
 console.log(JSON.stringify({status:result.status,commitReturned:true,sessionRowsRemoved:4,linkedRowsAbsent:true,nonselectedSessionsPreserved:true,applicationWrites:0,tokenUsability:'not_verified'}));
}catch(error){const code=(error as any)?.code;const failure={status:'cleanup_failed_or_uncertain',stage,commitReturned,sqlstate:typeof code==='string'&&/^[0-9A-Z]{5}$/.test(code)?code:null};await writeFile('.superpowers/m78-interrupted-session-cleanup-v3-failure.json',JSON.stringify(failure)+'\n',{flag:'wx'});console.log(JSON.stringify(failure));process.exitCode=1;}finally{await db.close();}

param(
  [Parameter(Mandatory=$true)][ValidateSet('cleanup')][string]$Mode,
  [Parameter(Mandatory=$true)][string[]]$OperationArguments
)
$ErrorActionPreference='Stop'
try {
  $workspace=[IO.Path]::GetFullPath('C:/Users/nimab/.codex/worktrees/4441/Neuvetra')
  $scriptFull=Join-Path $workspace '.superpowers/m78-interrupted-session-cleanup-v3.ts'
  if($Mode -ne 'cleanup' -or $OperationArguments.Count -ne 1 -or $OperationArguments[0] -ne 'exact-four-sessions'){throw 'argument count'}
  if((Get-FileHash -LiteralPath $scriptFull).Hash.ToLowerInvariant() -cne '20b6a58f409925b8a9c29982a85585cbfc4361e48c75301ebffe8a00c1b602a3'){throw 'cleanup changed'}
  $values=@()
  foreach($line in [IO.File]::ReadAllLines('C:/Users/nimab/Neuvetra/env.json.txt')){
    if($line -match '^\s*(?:export\s+)?DATABASE_URL\s*=\s*(.*?)\s*$'){
      $value=$Matches[1]
      if($value.StartsWith('"')){$value=ConvertFrom-Json $value}elseif($value.StartsWith("'") -and $value.EndsWith("'")){$value=$value.Substring(1,$value.Length-2)}
      $values+=$value
    }elseif($line -match '^\s*"DATABASE_URL"\s*:\s*("(?:[^"\\]|\\.)*")\s*,?\s*$'){$values+=(ConvertFrom-Json $Matches[1])}
  }
  if($values.Count -ne 1){throw 'connection selection'}
  $payload=@{operatorDatabaseUrl=[string]$values[0];operatorId='/root'} | ConvertTo-Json -Compress
  $start=[Diagnostics.ProcessStartInfo]::new()
  $start.FileName='C:/Users/nimab/.bun/bin/bun.exe'
  $start.WorkingDirectory=$workspace
  $start.ArgumentList.Add('run');$start.ArgumentList.Add($scriptFull);$start.ArgumentList.Add($Mode)
  foreach($argument in $OperationArguments){$start.ArgumentList.Add($argument)}
  $start.UseShellExecute=$false;$start.CreateNoWindow=$true
  $start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
  $process=[Diagnostics.Process]::Start($start)
  $process.StandardInput.Write($payload);$process.StandardInput.Close()
  $output=$process.StandardOutput.ReadToEndAsync();$errors=$process.StandardError.ReadToEndAsync()
  $process.WaitForExit()
  Write-Output $output.Result
  if($process.ExitCode -ne 0){Write-Output 'M78 private database operation failed; sensitive diagnostics withheld.';exit 1}
}catch{Write-Output 'M78 private database operation unavailable; sensitive diagnostics withheld.';exit 1}
